template<typename DisplayType>
inline void drawGeorgiaHeroClock(DisplayType& disp, int startX, int startY, int hour24, int minute) {
    int h12 = hour24 % 12;
    if (h12 == 0) h12 = 12;
    bool isPM = (hour24 >= 12);
    char buf[8];
    snprintf(buf, sizeof(buf), "%02d:%02d", h12, minute);

    // Clear stale cloud hero clock area (X: 16..265, Y: 76..165)
    disp.fillRect(startX, startY - 2, 250, 84, GxEPD_WHITE);

    int cur_x = startX;
    int cur_y = startY;

    for (int i = 0; buf[i] != '\0'; i++) {
        char c = buf[i];
        const GeorgiaGlyph* g = getGeorgiaHeroGlyph(c);
        if (g) {
            disp.drawBitmap(cur_x + g->x_offset, cur_y + g->y_offset, g->data, g->w, g->h, GxEPD_BLACK);
            cur_x += g->advance;
        }
    }

    // Baseline AM/PM
    const GeorgiaGlyph* ampm = isPM ? getGeorgiaPmGlyph() : getGeorgiaAmGlyph();
    disp.drawBitmap(cur_x + 8 + ampm->x_offset, 130 + ampm->y_offset, ampm->data, ampm->w, ampm->h, GxEPD_BLACK);
}
